// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"ethereum":{"slug":"ethereum","cat":"basics","en":"Ethereum (ETH)","contentLocale":"zh-Hans","term":"以太坊（Ethereum，ETH）","aka":["ETH","Ethereum","以太币","姨太"],"short":"以太坊是支持智能合约的开源区块链，原生币为 ETH，用于支付 Gas 费和质押，DeFi、NFT 和大量代币都运行在它上面。","body":[[["比特币","bitcoin"],"主要用于转账和价值储存，以太坊则像一台全球共享的计算机：开发者可以在上面部署",["智能合约","smart-contract"],"，做出",["去中心化交易所","dex"],"、",["借贷协议","defi-lending"],"、",["稳定币","stablecoin"],"和 ",["NFT","nft"],"。每次执行合约或转账都要消耗 Gas，Gas 费用 ETH 支付。"],"2022 年 9 月以太坊完成“合并”（The Merge），从工作量证明转为权益证明，不再靠矿机挖矿，而是由质押 ETH 的验证者出块。ETH 没有固定总量上限，供应变化取决于新发行量和被销毁的手续费。","由于主网拥堵时 Gas 费会很高，出现了 Arbitrum、Optimism、Base 等二层网络（L2），把交易放到二层处理再把结果提交回主网，费用通常低得多。提币时注意区分以太坊主网和各个 L2 网络。"],"example":"假设当前 Gas 价格为 20 gwei，一笔普通 ETH 转账消耗 21,000 Gas。手续费 = 21,000 × 20 gwei = 420,000 gwei = 0.00042 ETH。若 ETH 价格为 3,000 USDT，这笔转账约花 1.26 USDT。同样的操作若涉及复杂的 DeFi 合约，可能消耗 15 万 Gas 以上，费用会高出数倍。","mistakes":["钱包里只有 USDT 没有 ETH，结果连转账的 Gas 费都付不起。","把以太坊主网和 L2 网络当成同一个网络，充提时选错导致资产卡住。","以为 ETH 和 BTC 一样有 2100 万上限，其实 ETH 没有固定总量上限。"],"faq":[{"q":"以太坊和以太币有什么区别？","a":"以太坊指整个区块链网络，以太币（ETH）是这个网络的原生加密货币。日常交流中两者经常混用。"},{"q":"以太坊现在还能挖矿吗？","a":"不能。2022 年 9 月合并后，以太坊改为权益证明，出块由质押 ETH 的验证者完成。"}],"title":"什么是以太坊（ETH）？以太坊的含义与用途","description":"以太坊是什么、ETH 有哪些用途、Gas 费如何计算、合并后为何不再挖矿，以及主网和 L2 网络的区别，新手一篇看懂。","related":[["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"],["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。"],["proof-of-stake","权益证明（PoS）","权益证明（PoS）是一种共识机制，验证者通过质押代币获得出块和验证资格，作恶会被罚没质押，以太坊自 2022 年起采用。"],["layer-2","二层网络（Layer 2，L2）","二层网络（L2）是建立在一层区块链之上的扩容方案，在二层批量处理交易后把结果提交回主链，以更低的费用借用主链安全性。"],["defi","DeFi（去中心化金融）","DeFi（去中心化金融）是指运行在区块链智能合约上的金融服务，比如交易、借贷、质押和收益聚合，用户用自己的钱包直接参与，无需银行或交易所作为中介。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"layer-1":{"slug":"layer-1","cat":"basics","en":"Layer 1 (L1)","contentLocale":"zh-Hans","term":"一层网络（Layer 1，L1）","aka":["L1","Layer 1","公链","主网"],"short":"一层网络（L1）是指自己负责共识、安全和交易结算的基础区块链，比如比特币、以太坊、Solana 和 BNB Chain。","body":[["L1 就是“底层公链”。它有自己的",["节点","node"],"网络、共识机制和",["原生币","coin-vs-token"],"，交易最终记录在这条链上。L1 的原生币通常用来支付 ",["Gas 费","gas-fee"],"，在 ",["PoS","proof-of-stake"]," 链上还用于",["质押","staking"],"。"],[["区块链","blockchain"],"常被认为面临“不可能三角”：很难同时做到高度去中心化、高安全和高吞吐。不同 L1 取舍不同，有的追求去中心化和稳健，出块慢、费用随拥堵上升；有的追求高性能，硬件门槛更高、节点更少。"],"为了在不牺牲 L1 安全性的前提下扩容，以太坊生态发展出了 L2。对用户来说，判断一笔资产在哪条 L1 或 L2 上，决定了你要用哪种币付手续费、提币时选哪个网络。"],"example":"假设你要转 100 USDT。走以太坊主网（L1），拥堵时 Gas 可能要几美元；走波场 TRC20，手续费的计算方式又不同；走 Solana，通常只需不到 0.01 美元的 SOL。同样是 100 USDT，选择不同的 L1，到账时间和成本差别明显，但收款方必须支持你选的那条链。","mistakes":["以为 L1 越快越好，忽略了去中心化程度和安全性的差异。","提币时没确认收款方支持哪条链，选了对方不支持的网络。","把“公链”代币当成和链无关的普通代币，没准备好付 Gas 的原生币。"],"faq":[{"q":"L1 和 L2 有什么区别？","a":"L1 自己负责共识和结算；L2 把交易放在链下或另一层处理，再把结果提交到 L1，借用 L1 的安全性降低费用。"},{"q":"BNB Chain 是 L1 吗？","a":"通常被视为 L1，因为它有自己的验证者网络和原生币 BNB，独立完成共识和结算。"}],"title":"什么是 Layer 1（L1）？一层网络的含义","description":"Layer 1（一层网络）是什么？讲清 L1 公链的作用、不可能三角的取舍、L1 和 L2 的区别，以及转账时如何选择网络。","related":[["layer-2","二层网络（Layer 2，L2）","二层网络（L2）是建立在一层区块链之上的扩容方案，在二层批量处理交易后把结果提交回主链，以更低的费用借用主链安全性。"],["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"],["ethereum","以太坊（Ethereum，ETH）","以太坊是支持智能合约的开源区块链，原生币为 ETH，用于支付 Gas 费和质押，DeFi、NFT 和大量代币都运行在它上面。"],["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。"],["coin-vs-token","币和代币的区别（Coin vs Token）","币（Coin）通常指一条区块链自己的原生资产，如 BTC、ETH；代币（Token）则是基于已有区块链的智能合约发行的资产，如以太坊上的 USDT。"]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":null,"cta":false},"token-burn":{"slug":"token-burn","cat":"basics","en":"Token burn","contentLocale":"zh-Hans","term":"代币销毁（Token Burn）","aka":["Token burn","销毁","燃烧"],"short":"代币销毁是把代币发送到无人掌握私钥的地址或由合约直接注销，使其永久退出流通，从而减少总供应量。","body":[["销毁的常见方式是把代币转到“黑洞地址”，这个地址没有人知道",["私钥","private-key"],"，代币进去就再也转不出来。也有项目通过合约函数直接减少总供应量。所有销毁记录都可以在链上查证。"],["销毁的来源各不相同：有的项目用利润回购后销毁，比如 BNB 定期销毁；有的协议把部分手续费自动销毁，比如",["以太坊","ethereum"],"从 2021 年起销毁每笔交易的基础费；也有项目一次性销毁未分配的代币。"],["销毁减少供应，但不代表价格一定上涨。要看销毁量相对于",["流通量","circulating-supply"],"和新增发行量有多大。如果每年增发 5%、只销毁 1%，总供应仍在增加。还有些项目宣传“销毁”，销毁的却是本来就不会流通的锁仓代币，实际影响有限。"]],"example":["假设某代币流通 5 亿枚，项目方每季度用收入回购并销毁 500 万枚，一年共销毁 2,000 万枚，占流通量 4%。同一年里，",["质押","staking"],"奖励新增发行 3,000 万枚。合计下来，流通量从 5 亿枚增加到 5.1 亿枚，净增 2%。只看“销毁”标题，你会误以为它在通缩。"],"mistakes":["看到销毁公告就认为价格会涨，不看销毁规模和增发量。","没去链上核实，相信了项目方夸大的销毁数据。","把销毁未流通的锁仓代币当成减少了市场抛压。"],"faq":[{"q":"销毁的代币还能找回吗？","a":"发送到黑洞地址或通过合约注销的代币，没有任何人能再动用，因此视为永久退出流通。"},{"q":"以太坊会销毁 ETH 吗？","a":"会。自 2021 年 EIP-1559 升级后，每笔交易的基础费会被销毁，网络越繁忙，销毁的 ETH 越多。"}],"title":"什么是代币销毁（Token Burn）？含义与作用","description":"代币销毁是什么意思？讲清黑洞地址、回购销毁和手续费销毁的原理，以及为什么要把销毁量和增发量放在一起比较。","related":[["tokenomics","代币经济学（Tokenomics）","代币经济学是指一个代币的供应量、分配比例、解锁节奏、用途和销毁机制等设计，决定了代币未来的供需结构。"],["circulating-supply","流通量（Circulating Supply）","流通量是指当前已在市场上自由流通、可以被交易的代币数量，不包括仍处于锁仓或尚未发行的部分。"],["market-capitalization","市值（Market Cap）","市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。"],["coin-vs-token","币和代币的区别（Coin vs Token）","币（Coin）通常指一条区块链自己的原生资产，如 BTC、ETH；代币（Token）则是基于已有区块链的智能合约发行的资产，如以太坊上的 USDT。"]],"lesson":null,"coin":{"slug":"bnb","name":"BNB","symbol":"BNB"},"tool":null,"cta":false},"fud":{"slug":"fud","cat":"basics","en":"FUD","contentLocale":"zh-Hans","term":"FUD（恐惧、不确定、怀疑）","aka":["Fear, Uncertainty and Doubt","散布恐慌"],"short":"FUD 是 Fear、Uncertainty、Doubt 的缩写，指在市场上传播的恐惧、不确定和怀疑情绪或消息，常引发恐慌性抛售。","body":[["FUD 可能来自真实的负面消息，比如",["交易所","centralized-exchange"],"被盗、监管收紧、项目方出问题；也可能是夸大、断章取义甚至捏造的传言。币圈里有人会故意散布 FUD 压低价格，自己趁机低价买入。"],["看到负面消息时，先区分它是可核实的事实还是情绪化的说法。可以查看官方公告、",["链上数据","on-chain-analysis"],"（比如大额资金是否真的流出）和多个独立信源，而不是只看一条截图或一个群聊里的转述。"],"需要注意的是，并非所有负面信息都是 FUD。把一切坏消息都当成“有人在 FUD”同样危险，很多项目真正出事前都有人提出过质疑。关键在于核实，而不是站队。"],"example":["假设社交媒体上传言某交易所“暂停提币”，一个小时内你持有的平台币跌了 15%。你去查看：交易所官方公告说某一条链的钱包在维护，预计两小时恢复，其他链提币正常；链上数据也显示",["热钱包","hot-wallet"],"余额没有异常变化。如果你在恐慌中以 85 ",["USDT","usdt"]," 卖出原本 100 USDT 的仓位，而两小时后价格回到 98，你就因 FUD 多亏了 13 USDT。"],"mistakes":["看到一张截图就恐慌卖出，不去核实官方信息。","把所有批评都当作 FUD，忽视了真实的风险信号。","在恐慌中用市价单在流动性很差时卖出，额外承受大幅滑点。"],"faq":[{"q":"FUD 是什么意思？","a":"FUD 是 Fear、Uncertainty、Doubt 三个词的首字母缩写，指引发恐惧、不确定和怀疑的信息或情绪。"},{"q":"怎么判断一条消息是不是 FUD？","a":"看它能否被官方公告、链上数据或多家可靠媒体证实。无法核实、只靠情绪传播的消息更可能是 FUD。"}],"title":"FUD 是什么意思？币圈恐慌消息如何辨别","description":"FUD 在币圈是什么意思？讲清 FUD 从何而来、如何用官方公告和链上数据核实负面消息，以及为什么不是所有坏消息都是 FUD。","related":[["fomo","FOMO（错失恐惧）","FOMO（Fear of Missing Out）指害怕错过上涨行情而冲动买入的心理，在币圈常表现为追高和临时加仓。"],["bear-market","熊市（Bear Market）","熊市是指加密货币或其他资产价格在较长时间内持续下跌、市场情绪悲观、成交量和关注度明显下降的阶段，与之相对的是牛市。"],["fear-and-greed-index","恐惧与贪婪指数（Fear and Greed Index）","恐惧与贪婪指数是把价格波动、成交量、社交媒体热度、资金费率等数据综合成0到100分数的市场情绪指标，分数越低代表越恐惧，越高代表越贪婪。"],["on-chain-analysis","链上分析（On-chain analysis）","链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"别人说能帮你赚钱，先看他要什么"},"coin":null,"tool":null,"cta":false},"bid-ask-spread":{"slug":"bid-ask-spread","cat":"trading","en":"Bid-ask spread","contentLocale":"zh-Hans","term":"买卖价差（Bid-Ask Spread）","aka":["价差","点差","Spread","Bid-ask spread"],"short":"买卖价差是订单簿上最高买价与最低卖价之间的差额，代表立即买入再立即卖出所要承担的隐性成本。","body":["买方愿意付的最高价叫买一价（Bid），卖方愿意接受的最低价叫卖一价（Ask）。两者之间的差就是价差。你用市价买入时按卖一价成交，马上用市价卖出时按买一价成交，中间的差额就白白损失了。",["价差通常用占中间价的百分比表示。",["BTC","bitcoin"],"、",["ETH","ethereum"]," 的 ",["USDT","usdt"]," ",["交易对","trading-pair"],"在大",["交易所","centralized-exchange"],"价差往往很小，冷门小币可能有 0.5% 甚至更大的价差。行情剧烈波动或",["流动性","liquidity"],"撤离时，价差会突然扩大。"],"价差是手续费以外的交易成本，但很多新手忽视它。做市商靠持续挂买单和卖单、赚取价差来提供流动性。对于价差大的币，用限价单挂在买一或卖一附近，可以避免直接支付整个价差。"],"example":"假设某币买一价 0.995 USDT，卖一价 1.005 USDT，中间价 1.000，价差 0.01 USDT，即 1%。你用市价买入 1,000 USDT，得到约 995 枚；不考虑手续费马上卖出，只能按 0.995 卖，得到约 990 USDT，立刻损失约 10 USDT。同样操作在价差 0.01% 的 BTC/USDT 上，只损失约 0.1 USDT。","mistakes":["只比较交易所手续费，忽视了价差带来的更大成本。","在价差很大的冷门币上频繁用市价单进出。","在重大消息发布前后价差扩大时下市价单。"],"faq":[{"q":"买卖价差越小越好吗？","a":"对交易者来说，价差越小说明流动性越好，买卖的隐性成本越低，通常是更好的交易环境。"},{"q":"价差和滑点有什么区别？","a":"价差是下单前订单簿上买一和卖一的差距；滑点是下单后实际成交价偏离预期价的幅度，大单吃掉多档挂单时会产生滑点。"}],"title":"什么是买卖价差（Spread）？含义与计算","description":"买卖价差是什么意思？用例子讲清买一价和卖一价的差额如何成为隐性交易成本、价差和滑点的区别，以及如何降低价差成本。","related":[["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["market-maker","做市商（Market Maker）","做市商是在订单簿上持续同时挂出买单和卖单、为市场提供流动性的交易者或机构，主要通过买卖价差和交易所的挂单返佣获利。"],["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"屏幕上的价格，为什么不是我的成交价？"},"coin":null,"tool":"/rates","cta":false},"slippage":{"slug":"slippage","cat":"trading","en":"Slippage","contentLocale":"zh-Hans","term":"滑点（Slippage）","aka":["Slippage","滑价"],"short":"滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。","body":[["在",["中心化交易所","centralized-exchange"],"，滑点主要来自",["订单簿","order-book"],"深度不足：你的",["市价单","market-order"],"把最优价位的挂单吃完后，会继续以更差的价格成交，平均",["成交价","last-price"],"就偏离了下单时看到的价格。行情快速变化时，从你点下按钮到成交的一瞬间价格也可能已经变了。"],["在 ",["DEX","dex"]," 的 ",["AMM","amm"]," 流动性池里，滑点来自价格冲击：你买得越多，池子里这个代币越少，价格就越高。所以 DEX 会让你设置“滑点容忍度”，比如 0.5%，实际滑点超过这个值交易就会失败。"],"滑点容忍度设得太高，容易被夹子机器人（三明治攻击）抢跑，你按最差价格成交；设得太低，交易又经常失败白付 Gas。大额交易可以拆单分批，或改用限价单来控制成交价格。"],"example":"假设你在 DEX 用 10,000 USDC 买某代币，界面报价 1 枚 = 0.50 USDC，预计得到 20,000 枚。池子总流动性约 20 万美元，你这笔交易的价格冲击约 5%，实际只拿到约 19,000 枚，平均成交价约 0.526 USDC。如果你设置的滑点容忍度是 1%，这笔交易会直接失败；设成 10%，交易成功但多付了约 5%。","mistakes":["在 DEX 把滑点容忍度随手设成 10% 以上，被夹子机器人吃掉差价。","对流动性很浅的币一次性下大额市价单。","把滑点和手续费混为一谈，算成本时漏掉了滑点。"],"faq":[{"q":"滑点可以是正的吗？","a":"可以。如果下单后价格朝对你有利的方向移动，成交价可能比预期更好，这叫正滑点，但不能指望它。"},{"q":"怎么减少滑点？","a":"选择流动性好的交易对，用限价单代替市价单，大额交易拆分成多笔，并避开行情剧烈波动的时段。"}],"title":"什么是滑点？滑点的含义与如何减少","description":"滑点是什么意思？讲清 CEX 订单簿和 DEX 流动性池中滑点的来源、滑点容忍度怎么设，以及如何用限价单和拆单降低滑点。","related":[["bid-ask-spread","买卖价差（Bid-Ask Spread）","买卖价差是订单簿上最高买价与最低卖价之间的差额，代表立即买入再立即卖出所要承担的隐性成本。"],["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"],["amm","自动做市商（AMM）","自动做市商（AMM）是一种用流动性池和数学公式自动给代币定价的交易机制，不需要买卖双方挂单撮合，是 Uniswap 等去中心化交易所的核心。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"屏幕上的价格，为什么不是我的成交价？"},"coin":null,"tool":"/rates","cta":false},"trailing-stop":{"slug":"trailing-stop","cat":"trading","en":"Trailing stop","contentLocale":"zh-Hans","term":"移动止损（Trailing Stop）","aka":["跟踪止损","追踪止损","Trailing stop"],"short":"移动止损是一种会随价格朝有利方向移动而自动跟进的止损单，以固定比例或金额保持与最高价（或最低价）的距离，价格回撤到该距离时触发。","body":["普通止损价是固定的，移动止损则会“跟着走”。比如做多时设置 5% 回撤：价格上涨时，止损价随最高价一路上移；价格下跌时，止损价保持不动。一旦价格从最高点回落 5%，订单触发。","移动止损适合趋势行情，能让你在上涨中保留更多利润，而不必提前猜测顶部。它的缺点是在震荡行情里容易被来回扫出，回撤比例设得太小会频繁触发，设得太大又会回吐较多利润。",["不同",["交易所","centralized-exchange"],"对移动止损的叫法和参数不同，有的称“追踪委托”，可以设置激活价格（价格到达后才开始跟踪）和回调幅度，触发后多以市价成交。具体规则以平台说明为准。"]],"example":["假设你在 100 ",["USDT","usdt"]," 买入，设置 8% 的移动止损。价格涨到 120，止损价随之升到 120 × 92% = 110.4；继续涨到 135，止损价升到 124.2。之后价格回落到 124.2 时触发卖出，你在每枚上锁定了约 24 USDT 的利润（未计",["滑点","slippage"],"和手续费）。如果用固定止损 92，同样的行情下只能靠手动判断何时卖出。"],"mistakes":["在小币上设置太小的回撤比例，正常波动就被触发。","以为移动止损会在价格下跌时也往下调，其实只往有利方向移动。","没设激活价，开仓后马上开始跟踪，过早被扫出。"],"faq":[{"q":"移动止损的回撤比例设多少合适？","a":"没有通用数字。通常参考该币种的正常波动幅度，波动大的币需要更宽的回撤距离。"},{"q":"移动止损能用于做空吗？","a":"可以。做空时止损价随最低价下移，价格从最低点反弹到设定幅度时触发平仓。"}],"title":"什么是移动止损？跟踪止损的含义与用法","description":"移动止损（跟踪止损）是什么？用例子讲清止损价如何跟随价格上移、回撤比例怎么设，以及它在趋势和震荡行情中的优缺点。","related":[["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["take-profit","止盈单（Take-Profit）","止盈单是预先设定目标价，当价格朝有利方向达到该价位时自动卖出（或平仓）锁定利润的订单。"],["stop-limit-order","止损限价单（Stop-Limit Order）","止损限价单是包含触发价和限价两个价格的条件单，价格达到触发价后，系统以你设定的限价挂出一笔限价单。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"止盈止损，是计划，不是保险"},"coin":null,"tool":null,"cta":false},"mark-price":{"slug":"mark-price","cat":"derivatives","en":"Mark price","contentLocale":"zh-Hans","term":"标记价格（Mark Price）","aka":["标记价","mark price"],"short":"标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。","body":[["合约的",["最新成交价","last-price"],"可能因为一笔大单或",["流动性","liquidity"],"短暂枯竭而瞬间插针。如果用它来判断",["强平","liquidation"],"，很多仓位会被不合理地爆掉。所以",["交易所","centralized-exchange"],"改用标记价格：它一般以",["指数价格","index-price"],"为基础，再加上一个经过平滑处理的",["基差","futures-basis"],"或溢价部分。"],"标记价格主要用在三个地方：计算未实现盈亏、判断是否触发强平、计算资金费时的仓位价值。具体算法各交易所不同，有的取几个价格的中位数，有的使用移动平均的基差，可以在合约说明里找到。","因为标记价格和最新价会有差异，你看到的盈亏数字可能和按最新价心算的结果对不上。止损、止盈的触发价也常常可以选择按最新价或标记价格触发，要选清楚。"],"example":"假设 BTC 指数价格 60,000 USDT，你的多单强平价是 59,000。某个时刻，合约订单簿被一笔巨额市价卖单砸穿，最新成交价瞬间插到 58,000，又在一秒内回到 60,000。由于标记价格基于多家现货交易所的指数，只略微下降到约 59,980，你的仓位不会被强平。如果强平按最新价判断，这一秒就足以让你爆仓。","mistakes":["用最新成交价算强平距离，以为离强平还很远。","设置止损时没选触发价类型，结果止损在插针中被触发或没被触发。","以为标记价格永远不会插针，忽略现货市场整体剧烈波动时它也会大幅变化。"],"faq":[{"q":"标记价格和最新价有什么区别？","a":"最新价是合约市场最后一笔成交的价格，标记价格是基于指数价格计算的参考价，用于盈亏和强平计算，波动通常更平滑。"},{"q":"为什么我的未实现盈亏和最新价对不上？","a":"因为大多数交易所用标记价格计算未实现盈亏，而不是最新成交价，两者之间存在小幅差异。"}],"title":"标记价格是什么？为什么强平看标记价","description":"解释合约中标记价格的含义、它与指数价格和最新成交价的关系，以及为什么交易所用标记价格计算盈亏和判断强平。","related":[["index-price","指数价格（Index Price）","指数价格是交易所根据多家主流现货交易所的价格，按一定权重加权计算出的综合现货价格，用作标记价格和资金费率的基准。"],["liquidation-price","强平价（Liquidation Price）","强平价是标记价格达到后会触发仓位强制平仓的价格，由开仓价、杠杆倍数、维持保证金率以及保证金模式共同决定。"],["last-price","最新价（Last Traded Price）","最新价是某个交易对在订单簿上最后一笔实际成交的价格，也是交易软件和K线图上默认显示的实时价格。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"爆仓：谁按下了强制平仓按钮？"},"coin":null,"tool":"/funding-rates","cta":false},"instant-convert":{"slug":"instant-convert","cat":"exchange-features","en":"Convert (instant swap)","contentLocale":"zh-Hans","term":"闪兑（Convert）","aka":["闪兑","一键兑换","Convert","快捷兑换"],"short":"闪兑是交易所提供的一键兑换功能，你输入要兑换的币种和数量，平台给出一个锁定几秒的报价，确认后立即按报价完成兑换，无需在订单簿上挂单。","body":[["闪兑界面像货币兑换器，适合新手和小额换币：不用理解",["限价单","limit-order"],"、",["市价单","market-order"],"和盘口深度，看到的报价就是最终到账数量，很多平台还会显示“0手续费”。部分冷门币对没有直接的",["现货交易","spot-trading"],"对，闪兑可以在后台自动通过中间币完成。"],["所谓“0手续费”不等于没有成本。平台的报价通常已经包含一定的价差，也就是说，你得到的价格可能比现货",["订单簿","order-book"],"上的",["成交价","last-price"],"略差。小额兑换时差异不明显，金额较大或币种",["流动性","liquidity"],"较差时，差额可能比现货的挂单/吃单手续费更高。"],"如果你需要频繁或大额交易，可以把闪兑报价和现货市场的实时价格加手续费对比一下，再决定用哪种方式。"],"example":"假设你要用1,000 USDT换SOL。闪兑报价为150 USDT，标注0手续费，可得1,000 ÷ 150 ≈ 6.6667 SOL。同一时刻现货订单簿上的卖一价为149.5 USDT，用市价单买入可得约6.6890 SOL，扣除0.1%吃单手续费后约6.6823 SOL。两种方式相差约0.0156 SOL，约合2.3 USDT。金额放大到100,000 USDT时，同样的价差就是约230 USDT。","mistakes":["看到“0手续费”就以为闪兑一定最便宜，不对比现货价格。","大额兑换时只用闪兑，忽略报价中隐含的价差。","报价倒计时结束后匆忙确认新报价，没注意价格已经变化。"],"faq":[{"q":"闪兑和现货交易有什么区别？","a":"闪兑直接按平台报价成交，操作简单；现货交易在订单簿上撮合，可以挂限价单，价格更透明，但需要理解订单类型和手续费。"},{"q":"闪兑为什么没有手续费？","a":"很多平台不单独收取手续费，但成本通常已包含在报价的价差里，所以实际兑换价格可能比市场价略差。"}],"title":"什么是闪兑？一键兑换与现货交易对比","description":"交易所闪兑是什么？了解一键兑换的报价机制、“0手续费”背后的价差成本，并用实际数字对比闪兑和现货市价单的差异。","related":[["spot-trading","现货交易（Spot Trading）","现货交易是以当前市场价格直接买卖加密货币并即时完成交割的交易方式，买入后你真正持有这个币。"],["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。"],["bid-ask-spread","买卖价差（Bid-Ask Spread）","买卖价差是订单簿上最高买价与最低卖价之间的差额，代表立即买入再立即卖出所要承担的隐性成本。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"第一笔现货：从100到0.002枚"},"coin":null,"tool":null,"cta":false},"tokenized-stocks":{"slug":"tokenized-stocks","cat":"tokenized-assets","en":"Tokenized stocks","contentLocale":"zh-Hans","term":"代币化股票（Tokenized stocks）","aka":["股票代币","链上股票","美股代币"],"short":"代币化股票是把上市公司股票的价格和经济权益映射到区块链代币上的产品，通常由发行方托管真实股票并按1:1发行代币，可在交易所或链上交易。","body":[["典型做法是：发行方在证券市场买入并托管股票，再在",["区块链","blockchain"],"上发行等量代币，1枚代币对应1股（或一定比例）股票。用户可以用USDT、USDC等",["稳定币","stablecoin"],"购买，支持按小数单位买入，部分产品可以在链上转账，或在DeFi中使用。"],"代币化股票和直接持有股票的权利不一定相同。你持有的往往是对发行方的权益凭证，而不是登记在你名下的股票，通常没有投票权；分红可能以代币形式自动再投资或分发，各产品的处理方式不同。",["它与",["股票永续合约","stock-perpetuals"],"的区别在于：代币化股票是现货资产，没有",["杠杆","leverage"],"和",["资金费率","funding-rate"],"，也不会被",["强平","liquidation"],"；而股票永续合约是衍生品，可以做空和加杠杆。代币化股票的可用性受地区法规限制较多，很多产品不向美国等地区的用户开放。"]],"example":"假设某股票价格为200美元，你用100 USDC买入0.5枚对应的代币化股票。之后股价上涨10%到220美元，你的0.5枚代币价值约110 USDC，盈利10 USDC。如果公司每股派发1美元股息，按该产品的规则，你可能获得约0.5美元等值的分红，形式可能是稳定币或追加的股票代币。如果股价下跌10%，你的持仓同样变成约90 USDC，但不会因下跌而被强平。","mistakes":["以为持有代币化股票就等于在证券账户里持有股票，享有投票权等全部股东权利。","不看发行方的托管和赎回安排，忽视发行方本身的信用风险。","把代币化股票和股票永续合约混为一谈，搞不清是否有杠杆和强平。"],"faq":[{"q":"代币化股票能领分红吗？","a":"多数产品会把股息以稳定币或追加代币的形式分发或再投资，具体方式由发行方规定，需要查看产品说明。"},{"q":"代币化股票在美股休市时能交易吗？","a":"部分平台在休市时间也允许交易代币，但由于底层股票不交易，此时的价格可能与下一个开盘价有较大偏离。"}],"title":"什么是代币化股票？与股票永续合约有何不同","description":"代币化股票是什么？了解股票代币的托管和1:1发行机制、与直接持股在投票权和分红上的区别，以及与股票永续合约的差异。","related":[["stock-perpetuals","股票永续合约（Stock perpetuals）","股票永续合约是跟踪某只股票或股票指数价格、没有到期日的衍生品合约，用USDT等稳定币作保证金，可以做多做空并使用杠杆，通过资金费率与标的价格保持一致。"],["real-world-assets","现实世界资产（RWA）","现实世界资产（RWA）是指被代币化后在区块链上发行和流通的链下资产，例如国债、货币市场基金、私人信贷、房地产、黄金和股票等。"],["spot-bitcoin-etf","比特币现货ETF（Spot bitcoin ETF）","比特币现货ETF是在证券交易所上市、由基金直接持有真实比特币的交易所交易基金，投资者通过证券账户买卖份额，就能获得跟踪比特币价格的敞口。"],["usdc","USDC（美元币）","USDC 是由 Circle 公司发行、与美元 1:1 挂钩的稳定币，储备主要为现金和短期美国国债，以储备披露较透明著称，在 DeFi 和合规场景中使用广泛。"]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
